// Original schematic equipment art. Shapes are game affordances, not connector instructions.
const fitOrder=['saline','wrap','tubing','cable'];
export function arterialSignalReady(s){const a=s.aline;return a.teamInserted&&a.zero&&a.stopcock==='monitor'&&a.capped&&a.primed&&a.primeStage==='done'&&!a.bubbles.length&&a.pressure===300&&Math.abs(a.level-50)<=4;}
export function equipmentStep(s){const a=s.aline;if(fitOrder.some(x=>!a.fit.includes(x)))return 'fit';if(a.path.length<3)return 'prime-trace';if(!a.primed)return 'prime';if(a.primeStage!=='done')return 'flush';if(!a.capped&&!a.zero&&a.stopcock!=='air')return 'cap';if(a.pressure<300)return 'pressure';if(Math.abs(a.level-50)>4)return 'level';if(!a.zero)return a.stopcock==='air'?'zero':'stopcock';if(a.stopcock!=='monitor')return 'restore';if(!a.teamInserted)return 'insert-team';return 'line-check';}
export function equipmentAction(s){const step=equipmentStep(s),a=s.aline;return {
 fit:['fit',fitOrder.find(x=>!a.fit.includes(x)),{saline:'SLIDE SALINE INTO SLEEVE',wrap:'CLOSE THE WRAP',tubing:'CONNECT FLUID TUBING',cable:'CONNECT MONITOR CABLE'}[fitOrder.find(x=>!a.fit.includes(x))]],
 'prime-trace':['prime-trace',['bag','transducer','waste'][a.path.length],'TRACE NEXT CHECKPOINT'],prime:['prime',null,'START GRAVITY PRIME'],flush:['flush-tap',null,'TAP TO ADVANCE FLOW'],cap:['cap',null,'FIT NONVENTED CAPS'],pressure:['pressure',null,'SQUEEZE BULB'],level:['level',50,'ALIGN TO REFERENCE'],stopcock:['stopcock','air','TURN OFF → PATIENT'],zero:['zero',null,'ZERO TO ATMOSPHERE'],restore:['stopcock','monitor','TURN OFF → AIR + CAP'],'insert-team':['insert-team',null,'ASSIST TRAINED INSERTER']
}[step]||null;}
const pieceArt={
 saline:'<path d="M20 9h24v7H20z" fill="#9ab8b7"/><rect x="9" y="15" width="46" height="60" rx="11" fill="#e6f5e5" stroke="#35596a" stroke-width="3"/><path d="M13 42h38v20q0 8-8 8H21q-8 0-8-8z" fill="#81d7e6"/><rect x="17" y="25" width="30" height="23" rx="4" fill="#fff4d9"/><text x="32" y="35" text-anchor="middle" font-size="9" fill="#284555">STERILE</text><text x="32" y="44" text-anchor="middle" font-size="9" font-weight="bold" fill="#284555">SALINE</text><path d="M28 75v8h8v-8" fill="#a2cccc"/>',
 tubing:'<path d="M7 54Q34 78 49 53T27 28" fill="none" stroke="#44677a" stroke-width="12"/><path d="M7 54Q34 78 49 53T27 28" fill="none" stroke="#c4e5df" stroke-width="7"/><circle cx="26" cy="23" r="13" fill="#e1f2e7" stroke="#3c6677" stroke-width="4"/><circle cx="26" cy="23" r="6" fill="#83c6d1"/>',
 cable:'<path d="M12 67Q55 72 47 47L35 31" fill="none" stroke="#7267a1" stroke-width="7"/><rect x="18" y="8" width="31" height="27" rx="5" fill="#c7b6f0" stroke="#4d4c75" stroke-width="4"/><path d="M27 12v14m9-14v14" stroke="#f3e6ff" stroke-width="4"/>',
 wrap:'<path d="M8 18Q30 8 56 18V68Q30 78 8 68Z" fill="#d9bb79" stroke="#6f725d" stroke-width="3"/><path d="M34 18v50" stroke="#f7e7ba" stroke-width="7"/><path d="M12 40h39" stroke="#918869" stroke-width="10"/>',
 bulb:'<path d="M14 29Q3 12 8 7" fill="none" stroke="#304d63" stroke-width="5"/><path d="M17 24Q36 9 55 25Q73 47 53 66Q32 79 13 62Q0 44 17 24Z" fill="#b8a2e6" stroke="#3d5371" stroke-width="4"/><path d="M23 28q12-9 24-1" fill="none" stroke="#e3d6fb" stroke-width="4"/>',
 cap:'<path d="M13 28h38v28H13z" fill="#eef5e8" stroke="#42697a" stroke-width="4"/><path d="M20 30v22m9-22v22m9-22v22m9-22v22" stroke="#a6c6c7" stroke-width="3"/>'
};
const art=id=>`<svg viewBox="0 0 64 88" aria-hidden="true">${pieceArt[id]||pieceArt.cap}</svg>`;
const fitNames={saline:'Slide saline into the open sleeve',wrap:'Close the pressure sleeve wrap',tubing:'Connect the round fluid connector',cable:'Connect the keyed monitor cable'};
const button=(p,text,extra='',cls='')=>`<button type="button" data-p="${p}" ${extra} class="${cls}">${text}</button>`;
export function renderEquipment(s){
 const a=s.aline,step=equipmentStep(s),fit=fitOrder.find(x=>!a.fit.includes(x)),saline=a.fit.includes('saline'),wrapped=a.fit.includes('wrap'),tubing=a.fit.includes('tubing'),cable=a.fit.includes('cable'),routing=['stopcock','zero','restore'].includes(step),level=step==='level',flowing=a.primed&&a.primeStage!=='done',full=a.primeStage==='done',fluid=full?'#7edee5':'#bdcfd4';
 const flowPercent=a.flow;
 const flowPath=a.primeStage==='vent'?'M201 104V137H247L170 180V216':'M201 104V137H247V201H170V216';
 const portTarget=fit==='saline'||fit==='wrap'?'left:63%;top:24%':fit==='tubing'?'left:77%;top:57%':'left:88%;top:39%';
 const status=step==='fit'?{saline:'Slide the bag into the open sleeve.',wrap:'Fold the wrap around the bag.',tubing:'Round fluid connector → transducer.',cable:'Keyed cable → monitor port.'}[fit]:step==='prime-trace'?'Trace bag → transducer → waste.':step==='prime'?'Gravity prime · circuit off patient.':step==='flush'?`${a.primeStage==='vent'?'1 · Vent path':'2 · Remaining tubing'} → waste · hold / release`:step==='cap'?'Air cleared. Fit the nonvented caps.':step==='pressure'?`${a.pressure} / 300 mmHg · squeeze the bulb.`:level?'Drag the transducer to the atrial reference.':step==='stopcock'?'Turn OFF toward PATIENT.':step==='zero'?'Patient isolated · reference open to AIR.':step==='restore'?'Turn OFF toward AIR; restore the cap.':step==='insert-team'?'Closed, capped setup ready for the trained team.':'Check waveform, site and distal circulation.';
 let controls='';
 if(step==='fit'){
  controls=`<div class="p-equip-target ${fit==='saline'?'sleeve':fit==='wrap'?'wrap':fit}" data-equip-target="${fit}" style="${portTarget}" aria-hidden="true">${fit==='tubing'?'<i class="p-round-port"></i>':fit==='cable'?'<i class="p-key-port"></i>':fit==='saline'?'<span>↓</span>':'↶'}</div><button class="p-equip-piece ${fit}" data-p="fit" data-value="${fit}" data-drag="equipment" data-id="${fit}" aria-label="${fitNames[fit]}" style="left:43%;top:79%">${art(fit)}</button>`;
 }else if(step==='prime-trace'){
  controls=[['bag',63,35],['transducer',78,59],['waste',53,85]].map(([id,x,y],i)=>`<button class="p-fluid-node ${a.path.includes(id)?'done':''}" data-p="prime-trace" data-value="${id}" data-fluid-node="${id}" style="left:${x}%;top:${y}%" aria-label="Trace ${id}">${a.path.includes(id)?'✓':i+1}</button>`).join('');
 }else if(step==='flush'){
  controls=`<button class="p-flush-control" data-flow-hold aria-label="Hold to flow; release to stop" style="left:69%;top:77%"><span>↧</span><b>HOLD</b></button><div class="p-flow-readout">${Math.round(a.flow)}% · ${a.primeStage==='vent'?'VENT':'TUBING'}</div>`;
 }else if(step==='pressure')controls=`<button class="p-equip-piece bulb" data-p="pressure" aria-label="Squeeze pressure bulb" style="left:61%;top:80%">${art('bulb')}</button>`;
 else if(step==='cap')controls=`<button class="p-equip-piece cap" data-p="cap" aria-label="Fit nonvented caps" style="left:60%;top:78%">${art('cap')}</button>`;
 else if(level)controls=`<div class="p-atrial-reference"><span>RIGHT ATRIUM</span></div><button class="p-equip-transducer" data-equip-level style="top:clamp(24px,${100-a.level}%,calc(100% - 24px))" aria-label="Drag transducer to right atrial reference"><span>▥</span></button>`;
 else if(routing)controls=`<div class="p-route-art"><span class="p-route-patient">PATIENT PORT</span><span class="p-route-air">AIR${a.stopcock==='air'?' · OPEN':' · CAPPED'}</span><span class="p-route-sensor">TRANSDUCER</span><svg viewBox="0 0 160 110" aria-hidden="true"><path d="M7 65H141M80 65V7" stroke="#496879" stroke-width="14" fill="none"/><path d="${a.stopcock==='air'?'M80 7V65H141':'M7 65H141'}" stroke="#8ce5dc" stroke-width="7" fill="none"/></svg><button class="p-stopcock" data-p="route-turn" data-turn-dial aria-label="Turn stopcock: OFF toward ${step==='restore'?'air':'patient'}"><span class="p-off-pointer ${a.stopcock==='air'?'off-patient':'off-air'}">OFF</span><i>●</i></button></div>`;
 const bubbles=flowing?[0,1,2].filter(i=>a.primeStage==='vent'?i===0:a.bubbles.includes(['a','b','c'][i])).map((i)=>`<circle class="p-flow-bubble" cx="${a.primeStage==='vent'?235:247-(i===2?50:0)}" cy="${a.primeStage==='vent'?137:159+i*20}" r="5" fill="#f4ffff" stroke="#63a1b2" stroke-width="2"/>`).join(''):'';
 return `<div class="p-scene p-equipment-scene"><div class="p-scene-bar">${button('world','‹ BAY','','p-back')}<b>A-LINE · HANDS ON</b>${button('bedside','PATIENT','aria-label="Check patient; save setup"','p-bedside')}</div><div class="p-equipment-board ${routing?'routing':''}" ${step==='prime-trace'?'data-fluid-trace':''} data-equipment-board>
 <svg class="p-equipment-art" viewBox="0 0 320 240" preserveAspectRatio="none" aria-hidden="true">
 <rect x="5" y="14" width="108" height="213" rx="22" fill="#9fbec7"/><rect x="14" y="22" width="90" height="201" rx="18" fill="#e7edde"/><rect x="20" y="26" width="78" height="47" rx="13" fill="#fff4dc"/><ellipse cx="58" cy="55" rx="23" ry="26" fill="#dbb599"/><path d="M37 49Q30 21 60 25Q88 24 80 52L73 38Q57 42 43 37" fill="#d2d4ce"/><path d="M46 55h5m14 0h5" stroke="#455969" stroke-width="3" stroke-linecap="round"/><path d="M31 87Q58 77 86 87L99 203H19Z" fill="#8bd6c4" stroke="#4c8f94" stroke-width="2"/><path d="M30 94L20 141m67-47 12 47" stroke="#dbb599" stroke-width="13" stroke-linecap="round"/><path d="M44 117h9l5-12 8 26 6-14h12" fill="none" stroke="#55a99e" stroke-width="3"/>
 <path d="M233 14V227m-37 0h75M172 15h61" stroke="#628497" stroke-width="6" fill="none" stroke-linecap="round"/>
 <path d="M172 29Q180 18 191 29V104H172Z" fill="#d3bb83" stroke="#777d6e" stroke-width="2"/><rect x="191" y="27" width="38" height="77" rx="10" fill="#e5cf9a" stroke="#777d6e" stroke-width="2"/>
 ${saline?'<rect x="183" y="34" width="35" height="57" rx="8" fill="#eaf1e1"/><path d="M187 61h27v20q0 6-6 6h-15q-6 0-6-6z" fill="#85d7e0"/><path d="M198 92v10" stroke="#7db6c1" stroke-width="7"/>':''}
 ${wrapped?'<path d="M174 45h53v13h-53m0 20h53v13h-53" fill="#baaa7c"/><rect x="185" y="46" width="32" height="11" rx="4" fill="#e7d8b0"/>':''}
 ${!level?'<rect x="232" y="125" width="30" height="28" rx="6" fill="#b9a7e3" stroke="#555d82" stroke-width="3"/>':''}
 ${!level?`<path d="M201 104V137H234M247 153V201H170V216" fill="none" stroke="#627f90" stroke-width="11" stroke-dasharray="${tubing?'none':'4 5'}" stroke-linejoin="round"/>`:''}
 ${tubing&&!level?`<path d="M201 104V137H247V201H170V216" fill="none" stroke="${fluid}" stroke-width="6" stroke-linejoin="round"/>`:''}
 ${a.primed&&!level&&a.stopcock==='waste'&&!a.capped?`<path d="M247 137L170 180V216" fill="none" stroke="${a.primeStage==='vent'?'#aac9cc':'#98d5d8'}" stroke-width="7"/><path class="p-liquid-progress" d="${flowPath}" fill="none" stroke="#5dcada" stroke-width="6" pathLength="100" stroke-dasharray="${full?100:flowPercent} 100"/>`:''}
 ${level?`<path data-level-fluid d="M201 104V216H247V201H170V207" fill="none" stroke="#7edee5" stroke-width="7"/><path data-level-cable d="M260 216H283V72" fill="none" stroke="#8476bb" stroke-width="5"/>`:''}
 ${a.capped||a.stopcock==='air'?'<rect x="162" y="207" width="16" height="9" rx="3" fill="#f4f8e9" stroke="#547786" stroke-width="3"/>':''}
 ${cable&&!level?'<path d="M260 135H283V72" stroke="#8476bb" stroke-width="5" fill="none"/>':''}
 ${a.stopcock==='waste'&&!a.capped?'<path d="M152 219l6 14h26l6-14" fill="#c8e2df" stroke="#5f8b98" stroke-width="3"/><text x="171" y="230" font-size="9" fill="#31586c" text-anchor="middle">WASTE</text>':'<text x="171" y="229" font-size="10" fill="#31586c" text-anchor="middle">CAPPED</text>'}
 <circle cx="143" cy="65" r="18" fill="#183f52" stroke="#819b9d" stroke-width="4"/><path d="M143 65l${-9+a.pressure/15} -9" stroke="#eed39a" stroke-width="3"/><text x="143" y="96" font-size="11" font-weight="bold" fill="#244a5d" text-anchor="middle">${a.pressure} mmHg</text>
 ${bubbles}</svg>
 <button class="p-mini-monitor" data-p="monitor" aria-label="Zoom bedside monitor"><small>ART</small><b>${arterialSignalReady(s)?'⌁':'—'}</b><span>${a.teamInserted?'VIEW':'SETUP'}</span></button>
 ${controls}${step==='fit'?'<div class="p-prepared-note">Sterile kit prepared · bag air removed</div>':''}</div><div class="p-equipment-cue" aria-live="off">${status}</div></div>`;
}
